const origen = $('Prepare translation').item.json;
const respuesta = $json.body ?? $json;
const choice = respuesta.choices?.[0];

if (choice?.finish_reason === 'length') {
  throw new Error(
    `La traducción a ${origen.idioma_destino} ha quedado cortada.`
  );
}

if (choice?.message?.refusal) {
  throw new Error('La IA no ha generado la traducción.');
}

const raw = choice?.message?.content;

if (typeof raw !== 'string' || !raw.trim()) {
  throw new Error('La traducción está vacía.');
}

let traduccion;

try {
  traduccion = JSON.parse(
    raw.trim()
      .replace(/^```(?:json)?\s*/i, '')
      .replace(/\s*```$/, '')
  );
} catch {
  throw new Error('La traducción no contiene un JSON válido.');
}

const campos = [
  'titulo_seo',
  'keyword',
  'metadescripcion',
  'slug',
  'contenido'
];

for (const campo of campos) {
  if (
    typeof traduccion?.[campo] !== 'string' ||
    !traduccion[campo].trim()
  ) {
    throw new Error(`Falta el campo traducido: ${campo}`);
  }
}

const titulo = traduccion.titulo_seo.trim();
const keyword = traduccion.keyword.trim();
const contenido = traduccion.contenido.trim();



// Recalcular las estadísticas de la versión traducida.
const texto = contenido
  .replace(/<[^>]*>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const palabras = (
  texto.match(/[\p{L}\p{N}]+(?:['’\-][\p{L}\p{N}]+)*/gu) || []
).length;

// Quitar el prompt y conservar la identificación del artículo.
const { prompt, ...datos } = origen;

return {
  json: {
    ...datos,
    property_articulo: contenido,
    titulo_generado: titulo,
    keyword_generada: keyword,
    metadescripcion_generada: traduccion.metadescripcion.trim(),
    slug_generado: traduccion.slug.trim(),
    numero_palabras: palabras,
    numero_caracteres: Array.from(texto).length,
    es_original: false,
    ok: true
  }
};

if ($json.es_original === true) {
  throw new Error('Aquí debe entrar la versión para traducir, no el original.');
}

if (!$json.idioma_destino || !$json.property_articulo) {
  throw new Error('Falta el idioma de destino o el artículo.');
}

const original = {
