={{ (() => {
  const codigos = {
    catalan: 'ca',
    castella: 'es',
    castellano: 'es',
    espanol: 'es',
    ca: 'ca',
    es: 'es'
  };

  const versiones = $json.versiones;

  if (!Array.isArray(versiones) || versiones.length < 2) {
    throw new Error('Faltan las dos versiones para enlazar en Polylang.');
  }

  const translations = {};

  for (const version of versiones) {
    const idioma = String(version.idioma || '')
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .trim()
      .toLowerCase();

    const codigo = codigos[idioma];
    const id = Number(version.post_id);

    if (!codigo) {
      throw new Error('Idioma no configurado para Polylang: ' + version.idioma);
    }

    if (!Number.isSafeInteger(id) || id <= 0) {
      throw new Error('Falta un ID válido para: ' + version.idioma);
    }

    if (translations[codigo]) {
      throw new Error('Idioma repetido: ' + version.idioma);
    }

    translations[codigo] = id;
  }

  return JSON.stringify({ translations });
})() }}
